css:
.it-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.it-stage canvas { touch-action: none; cursor: grab; }
.it-stage canvas.holding { cursor: grabbing; }
.it-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; }
.it-ask { margin: 0; font-size: 19px; line-height: 1.45; padding: 6px 12px; border-left: 5px solid var(--accent); background: #f3f6fb; border-radius: 0 10px 10px 0; }

